(async () => {
 const {store,actions}=window.__gitgood;
 const pause=()=>new Promise(r=>setTimeout(r,80));
 const wait=async f=>{for(let i=0;i<100;i++){if(f())return;refresh();position();await pause();}throw Error('Diff did not settle: '+JSON.stringify({scroll:document.querySelector('.diff-body')?.scrollTop, mode:store.get().settings.diffViewMode,marks:[...document.querySelectorAll('.word-add,.word-del')].slice(0,3).map(e=>e.textContent)}));};
 const assert=(v,message)=>{if(!v)throw Error(message);};
 let refresh=()=>{};
 let position=()=>{};
 await actions.addLocalRepository(__REPO_PATH__);await pause();
 await actions.updateSettings({diffSyntaxHighlighting:false,diffShowIntraline:true,diffViewMode:'unified',diffWrapLines:false});
 const count=250;
 const show=(oldWord,newWord)=>{
  const lines=['delete','add'].flatMap(type=>Array.from({length:count},(_,i)=>({type,text:`const value${i} = ${type==='delete'?oldWord:newWord};`,oldLineNumber:type==='delete'?i+1:null,newLineNumber:type==='add'?i+1:null})));
  const diff={kind:'text',oldPath:'src/app.ts',newPath:'src/app.ts',language:'typescript',oldContent:null,newContent:null,hasCRLF:false,lineCount:lines.length,hunks:[{header:'@@ -1,250 +1,250 @@',oldStart:1,oldLines:count,newStart:1,newLines:count,lines}]};
  const apply=()=>store.set(s=>({changes:{...s.changes,selectedPaths:['src/app.ts']},diff:{...s.diff,key:'working:src/app.ts|ws=false',diff,loading:false,error:null}}));apply();refresh=apply;
 };
 const marks=cls=>[...document.querySelectorAll('.'+cls)].map(e=>e.textContent);
 const expectMarks=async(cls,word)=>{await wait(()=>marks(cls).includes(word));assert(marks(cls).every(v=>v===word),'Incorrect '+cls+' highlights');};
 show('oldValue','newValue');await expectMarks('word-del','oldValue');await pause();
 const body=document.querySelector('.diff-body');body.style.height='300px';body.style.flex='none';await pause();
 position=()=>{const el=document.querySelector('.diff-body');el.scrollTop=el.scrollHeight;el.dispatchEvent(new Event('scroll',{bubbles:true}));};position();await expectMarks('word-add','newValue');
 position=()=>{const el=document.querySelector('.diff-body');el.scrollTop=0;el.dispatchEvent(new Event('scroll',{bubbles:true}));};position();await expectMarks('word-del','oldValue');
 await actions.updateSettings({diffViewMode:'split'});await expectMarks('word-del','oldValue');await expectMarks('word-add','newValue');
 position=()=>{const el=document.querySelector('.diff-body');el.scrollTop=el.scrollHeight;el.dispatchEvent(new Event('scroll',{bubbles:true}));};position();await wait(()=>document.querySelector('tr[data-new-line="250"]'));await expectMarks('word-add','newValue');
 await actions.updateSettings({diffShowIntraline:false});await wait(()=>!document.querySelector('.word-add,.word-del'));
 await actions.updateSettings({diffShowIntraline:true});await expectMarks('word-add','newValue');
 show('previousIdentifier','replacementIdentifier');await expectMarks('word-add','replacementIdentifier');await expectMarks('word-del','previousIdentifier');
 return JSON.stringify({passed:true});
})()
